import urllib.request, concurrent.futures, json
from pathlib import Path
v=json.loads(Path('comparison_view.json').read_text())
urls={
'megadock_readme':'https://raw.githubusercontent.com/akiyamalab/MEGADOCK/9575280c875732553266e26adc607dd892b02616/README.md',
'megadock_license':'https://raw.githubusercontent.com/akiyamalab/MEGADOCK/9575280c875732553266e26adc607dd892b02616/LICENSE',
'pinder_license':'https://raw.githubusercontent.com/pinder-org/pinder/ebeb28a2f8411363cef722b7d293c978f7442672/LICENSE',
'pinder_readme':'https://raw.githubusercontent.com/pinder-org/pinder/ebeb28a2f8411363cef722b7d293c978f7442672/README.md',
'cuda_license':'https://raw.githubusercontent.com/NVIDIA/cuda-samples/v12.8/LICENSE'}
items=[(k,u,'GET') for k,u in urls.items()]
items += [(i['id']+'/'+key,i['spec'][key]['url'],'HEAD') for i in v['inputs'] for key in ['receptor_source','ligand_source','reference']]
def get(it):
 k,u,m=it
 try:
  with urllib.request.urlopen(urllib.request.Request(u,method=m),timeout=25) as r:
   body=r.read().decode() if m=='GET' else None
   return k,dict(url=u,method=m,status=r.status,content_length=r.headers.get('Content-Length'),text=body)
 except Exception as e:return k,dict(url=u,method=m,error=str(e))
results=dict(concurrent.futures.ThreadPoolExecutor(max_workers=8).map(get,items))
Path('intake/evidence.json').write_text(json.dumps(results,indent=2)+'\\n')
for k,r in results.items():
 print(k,json.dumps({a:b for a,b in r.items() if a"'!='"'text'}))
 if r.get('text'): print(r['text'][:18000])
PY"

